"""Hand-drawn SVG figures for the lessons - computed, never fetched or generated by a model.

Every lesson already says in words what the student should draw ("a Hasse diagram for divisibility on
{1,2,3,4,6,12}..."). This module draws that picture, so the page shows the figure and the sentence under it.
Pure Python + SVG: works offline, costs nothing, and looks the same every time.

    from indiclearn.studio.courses import diagrams
    diagrams.render("dsma", "posets")   -> "<svg ...>...</svg>" or None

Figures live in diagrams_u1.py ... diagrams_u6.py, one module per unit; each registers topic id -> builder.
Colours are the theme's CSS variables, so a figure follows the app's palette.
"""

from __future__ import annotations

import math
from typing import Any, Callable
from xml.sax.saxutils import escape

# ---------------------------------------------------------------- palette (frontend/css/theme.css)
INK = "var(--ink,#1F1B14)"
INK2 = "var(--ink-2,#4A4336)"
MUTED = "var(--muted,#6E6553)"
GOLD = "var(--gold,#8C6418)"
GOLD2 = "var(--gold-2,#CFA444)"
GOLD_SOFT = "var(--gold-soft,#F3E7C5)"
GOLD_WASH = "var(--gold-wash,#FBF4E0)"
LINE = "var(--line-2,#D9CDB0)"
SURFACE = "var(--surface,#FFFFFF)"
SURFACE2 = "var(--surface-2,#F6F1E6)"
GOOD = "var(--good,#4E7A4A)"
GOOD_SOFT = "var(--good-soft,#E3EFDF)"
BAD = "var(--bad,#A0463B)"
BAD_SOFT = "var(--bad-soft,#F6DDD8)"
INFO = "var(--info,#4F7BA6)"
WARN = "var(--warn,#C7862B)"
WARN_SOFT = "var(--warn-soft,#FAEBD0)"

SANS = "var(--sans,Inter,system-ui,sans-serif)"
MONO = "ui-monospace,SFMono-Regular,Menlo,monospace"


def esc(s: Any) -> str:
    return escape(str(s))


def _attrs(kw: dict[str, Any]) -> str:
    out = []
    for k, v in kw.items():
        if v is None:
            continue
        out.append(f'{k.replace("_", "-")}="{esc(v)}"')
    return (" " + " ".join(out)) if out else ""


# ---------------------------------------------------------------- primitives
def svg(width: int, height: int, body: str, label: str = "") -> str:
    """One figure. Scales to the column width; the viewBox fixes the drawing's own coordinates."""
    defs = (
        "<defs>"
        f'<marker id="dg-a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">'
        f'<path d="M0 0L10 5L0 10z" fill="{LINE}"/></marker>'
        f'<marker id="dg-ag" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">'
        f'<path d="M0 0L10 5L0 10z" fill="{GOLD}"/></marker>'
        f'<marker id="dg-ad" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">'
        f'<path d="M0 0L10 5L0 10z" fill="{INK2}"/></marker>'
        f'<marker id="dg-ab" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">'
        f'<path d="M0 0L10 5L0 10z" fill="{INFO}"/></marker>'
        "</defs>"
    )
    return (f'<svg class="dgm" viewBox="0 0 {width} {height}" width="100%" role="img" '
            f'aria-label="{esc(label)}" font-family="{SANS}" font-size="13">{defs}{body}</svg>')


def text(x: float, y: float, s: Any, size: float = 13, fill: str = INK, anchor: str = "middle",
         weight: str | int = 400, italic: bool = False, mono: bool = False, **kw: Any) -> str:
    extra = _attrs(kw)
    fam = f' font-family="{MONO}"' if mono else ""
    it = ' font-style="italic"' if italic else ""
    return (f'<text x="{x:.1f}" y="{y:.1f}" font-size="{size}" fill="{fill}" text-anchor="{anchor}" '
            f'font-weight="{weight}"{fam}{it}{extra}>{esc(s)}</text>')


def lines(x: float, y: float, rows: list[str], size: float = 12.5, fill: str = INK2, anchor: str = "middle",
          leading: float = 16, **kw: Any) -> str:
    return "".join(text(x, y + i * leading, r, size, fill, anchor, **kw) for i, r in enumerate(rows))


def rect(x: float, y: float, w: float, h: float, fill: str = "none", stroke: str = LINE,
         rx: float = 8, sw: float = 1.25, **kw: Any) -> str:
    return (f'<rect x="{x:.1f}" y="{y:.1f}" width="{w:.1f}" height="{h:.1f}" rx="{rx}" fill="{fill}" '
            f'stroke="{stroke}" stroke-width="{sw}"{_attrs(kw)}/>')


def circle(cx: float, cy: float, r: float, fill: str = "none", stroke: str = LINE, sw: float = 1.25, **kw: Any) -> str:
    return (f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="{r:.1f}" fill="{fill}" stroke="{stroke}" '
            f'stroke-width="{sw}"{_attrs(kw)}/>')


def line(x1: float, y1: float, x2: float, y2: float, stroke: str = LINE, sw: float = 1.25,
         dash: str | None = None, **kw: Any) -> str:
    d = f' stroke-dasharray="{dash}"' if dash else ""
    return (f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="{stroke}" '
            f'stroke-width="{sw}"{d}{_attrs(kw)}/>')


_MARKERS = {LINE: "dg-a", GOLD: "dg-ag", INK2: "dg-ad", INFO: "dg-ab"}


def arrow(x1: float, y1: float, x2: float, y2: float, stroke: str = LINE, sw: float = 1.25,
          dash: str | None = None, shrink: float = 0, both: bool = False) -> str:
    """A straight arrow. `shrink` pulls both ends back (so it stops at a circle's edge)."""
    if shrink:
        dx, dy = x2 - x1, y2 - y1
        d = math.hypot(dx, dy) or 1
        ux, uy = dx / d, dy / d
        x1, y1, x2, y2 = x1 + ux * shrink, y1 + uy * shrink, x2 - ux * shrink, y2 - uy * shrink
    m = _MARKERS.get(stroke, "dg-a")
    da = f' stroke-dasharray="{dash}"' if dash else ""
    start = f' marker-start="url(#{m})"' if both else ""
    return (f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="{stroke}" stroke-width="{sw}"'
            f'{da} marker-end="url(#{m})"{start}/>')


def path(d: str, fill: str = "none", stroke: str = LINE, sw: float = 1.25, arrowhead: bool = False,
         dash: str | None = None, **kw: Any) -> str:
    m = f' marker-end="url(#{_MARKERS.get(stroke, "dg-a")})"' if arrowhead else ""
    da = f' stroke-dasharray="{dash}"' if dash else ""
    return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}"{m}{da}{_attrs(kw)}/>'


def box(x: float, y: float, w: float, h: float, label: str | list[str], fill: str = SURFACE,
        stroke: str = LINE, size: float = 13, weight: str | int = 500, rx: float = 8,
        text_fill: str = INK, sw: float = 1.25) -> str:
    """A labelled box; a list of strings becomes centred lines."""
    rows = [label] if isinstance(label, str) else list(label)
    cy = y + h / 2 - (len(rows) - 1) * 8 + 4.5
    body = rect(x, y, w, h, fill, stroke, rx, sw)
    body += "".join(text(x + w / 2, cy + i * 16, r, size, text_fill, weight=weight) for i, r in enumerate(rows))
    return body


def diamond(cx: float, cy: float, w: float, h: float, label: str | list[str], fill: str = GOLD_WASH,
            stroke: str = GOLD2, size: float = 12.5) -> str:
    rows = [label] if isinstance(label, str) else list(label)
    pts = f"{cx - w / 2},{cy} {cx},{cy - h / 2} {cx + w / 2},{cy} {cx},{cy + h / 2}"
    out = f'<polygon points="{pts}" fill="{fill}" stroke="{stroke}" stroke-width="1.25"/>'
    top = cy - (len(rows) - 1) * 7 + 4.5
    return out + "".join(text(cx, top + i * 14, r, size, INK, weight=500) for i, r in enumerate(rows))


def node(cx: float, cy: float, label: Any, r: float = 19, fill: str = SURFACE, stroke: str = GOLD,
         size: float = 13, text_fill: str = INK, sw: float = 1.5) -> str:
    return circle(cx, cy, r, fill, stroke, sw) + text(cx, cy + size / 3, label, size, text_fill, weight=600)


def table(x: float, y: float, cols: list[str], rows: list[list[Any]], cw: float | list[float] = 74,
          rh: float = 26, highlight: int | None = None, head_fill: str = GOLD_SOFT,
          cell_fill: Callable[[int, int, Any], str] | None = None, size: float = 12.5,
          mono: bool = True) -> str:
    """A grid with a header row. `highlight` tints one column (the answer column of a truth table)."""
    widths = [cw] * len(cols) if isinstance(cw, (int, float)) else list(cw)
    xs = [x]
    for w in widths:
        xs.append(xs[-1] + w)
    total, height = xs[-1] - x, rh * (len(rows) + 1)
    out = ""
    if highlight is not None:
        out += rect(xs[highlight], y, widths[highlight], height, GOLD_WASH, "none", 0)
    out += rect(x, y, total, rh, head_fill, "none", 0)
    for j, c in enumerate(cols):
        out += text(xs[j] + widths[j] / 2, y + rh / 2 + 4.5, c, size, INK, weight=600, mono=mono)
    for i, row in enumerate(rows):
        yy = y + rh * (i + 1)
        for j, v in enumerate(row):
            if cell_fill:
                f = cell_fill(i, j, v)
                if f:
                    out += rect(xs[j], yy, widths[j], rh, f, "none", 0)
            out += text(xs[j] + widths[j] / 2, yy + rh / 2 + 4.5, v, size, INK2, mono=mono)
    for j in range(len(cols) + 1):
        out += line(xs[j], y, xs[j], y + height, LINE, 1)
    for i in range(len(rows) + 2):
        out += line(x, y + rh * i, x + total, y + rh * i, LINE, 1)
    return out


def axes(ox: float, oy: float, half: float, xlab: str = "", ylab: str = "", ticks: int = 0,
         step: float = 0, grid: bool = False) -> str:
    """A 2D coordinate cross centred at (ox, oy), reaching `half` pixels each way."""
    out = ""
    if grid and step:
        n = int(half // step)
        for k in range(-n, n + 1):
            out += line(ox + k * step, oy - half, ox + k * step, oy + half, LINE, 0.6)
            out += line(ox - half, oy + k * step, ox + half, oy + k * step, LINE, 0.6)
    out += arrow(ox - half, oy, ox + half, oy, MUTED, 1.1)
    out += arrow(ox, oy + half, ox, oy - half, MUTED, 1.1)
    if ticks and step:
        for k in range(-ticks, ticks + 1):
            if not k:
                continue
            out += line(ox + k * step, oy - 3.5, ox + k * step, oy + 3.5, MUTED, 1)
            out += line(ox - 3.5, oy + k * step, ox + 3.5, oy + k * step, MUTED, 1)
    if xlab:
        out += text(ox + half + 2, oy + 15, xlab, 12, MUTED, "end", italic=True)
    if ylab:
        out += text(ox + 6, oy - half + 2, ylab, 12, MUTED, "start", italic=True)
    return out


def vector(ox: float, oy: float, dx: float, dy: float, label: str = "", color: str = GOLD,
           sw: float = 2, dash: str | None = None, lab_dx: float = 10, lab_dy: float = -6,
           size: float = 12.5) -> str:
    """An arrow from the origin of a plot; dy is in screen pixels (already flipped by the caller)."""
    out = arrow(ox, oy, ox + dx, oy + dy, color, sw, dash)
    if label:
        out += text(ox + dx + lab_dx, oy + dy + lab_dy, label, size, color, "middle", weight=600, italic=True)
    return out


def caption(x: float, y: float, s: str, anchor: str = "middle", size: float = 11.5) -> str:
    return text(x, y, s, size, MUTED, anchor)


def legend(x: float, y: float, items: list[tuple[str, str]], gap: float = 150, size: float = 11.5) -> str:
    """items = [(colour, words)], laid out left to right on one line."""
    out = ""
    for i, (col, lab) in enumerate(items):
        xx = x + i * gap
        out += rect(xx, y - 8, 11, 11, col, col if col != "none" else LINE, 3, 1)
        out += text(xx + 17, y + 1.5, lab, size, MUTED, "start")
    return out


def brace(x: float, y1: float, y2: float, label: str = "", left: bool = True, color: str = MUTED) -> str:
    """A curly brace down the side of something, with a label beside it."""
    w = 9 if left else -9
    mid = (y1 + y2) / 2
    d = (f"M{x} {y1}q{-w} 0 {-w} 9V{mid - 9}q0 9 {-w} 9q{w} 0 {w} 9V{y2 - 9}q0 9 {w} 9")
    out = path(d, "none", color, 1.2)
    if label:
        out += text(x - w * 2.2, mid + 4, label, 12, color, "end" if left else "start", italic=True)
    return out


# ---------------------------------------------------------------- registry
_REG: dict[str, dict[str, Callable[[], str]]] = {}


def register(subject: str, topic: str) -> Callable[[Callable[[], str]], Callable[[], str]]:
    def deco(fn: Callable[[], str]) -> Callable[[], str]:
        _REG.setdefault(subject, {})[topic] = fn
        return fn

    return deco


_LOADED = False


def _load() -> None:
    """Import the per-unit figure modules once. A missing or broken unit must not hide the others."""
    global _LOADED
    if _LOADED:
        return
    _LOADED = True
    import importlib
    import logging

    for n in range(1, 7):
        try:
            importlib.import_module(f"indiclearn.studio.courses.diagrams_u{n}")
        except ImportError:
            pass
        except Exception:
            logging.getLogger(__name__).exception("diagrams_u%d failed to import", n)


def render(subject: str, topic: str) -> str | None:
    """The figure for one lesson, or None when that topic has none."""
    _load()
    fn = _REG.get(subject, {}).get(topic)
    if fn is None:
        return None
    try:
        return fn()
    except Exception:  # a broken figure must never take down the lesson
        import logging

        logging.getLogger(__name__).exception("diagram %s/%s failed", subject, topic)
        return None


def have(subject: str) -> set[str]:
    _load()
    return set(_REG.get(subject, {}))
